    def begin_call(self, call_id: str, customer_id: str, phone: str) -> None:
        self._sessions[call_id] = CallSession(
            call_id=call_id,
            customer_id=customer_id,
            phone=phone,
        )

    def _get_slot_lock(self, slot_id: str) -> asyncio.Lock:
        lock = self._slot_locks.get(slot_id)
        if lock is None:
            lock = asyncio.Lock()
            self._slot_locks[slot_id] = lock
        return lock

    async def process_booking_turn(
        self,
        call_id: str,
        slot_id: str,
        crm_notify: Callable[[str, str], Awaitable[None]],
    ) -> dict:
        session = self._sessions.get(call_id)
        if session is None:
            raise KeyError(f"Unknown call_id: {call_id}")

        async with self._get_slot_lock(slot_id):
            if slot_id not in self._open_slots or slot_id in self._pending_slots:
                return {
                    "call_id": session.call_id,
                    "customer_id": session.customer_id,
                    "phone": session.phone,
                    "booked": False,
                    "slot_id": slot_id,
                }
            # Reserve slot atomically before yielding to external I/O
            self._open_slots.remove(slot_id)
            self._pending_slots.add(slot_id)

        try:
            await asyncio.sleep(0.01)
            await crm_notify(session.customer_id, slot_id)
        except Exception:
            async with self._get_slot_lock(slot_id):
                self._pending_slots.discard(slot_id)
                self._open_slots.add(slot_id)
            raise
        else:
            async with self._get_slot_lock(slot_id):
                self._pending_slots.discard(slot_id)
                self._bookings[slot_id] = session.customer_id

        return {
            "call_id": session.call_id,
            "customer_id": session.customer_id,
            "phone": session.phone,
            "booked": True,
            "slot_id": slot_id,
        }

    def get_booked_customer(self, slot_id: str) -> Optional[str]:
        return self._bookings.get(slot_id)

    def is_slot_open(self, slot_id: str) -> bool:
        return slot_id in self._open_slots

"""Reference solution for Drill 3: CRM Booking Webhook Worker (Retries & Idempotency)."""

from __future__ import annotations

import asyncio
import json
from typing import Awaitable, Callable


class WebhookBookingWorker:
    def __init__(self) -> None:
        self._results: dict[str, dict] = {}
        self._payload_fingerprints: dict[str, str] = {}
        self._event_locks: dict[str, asyncio.Lock] = {}

    def _fingerprint(self, payload: dict) -> str:
        return json.dumps(payload, sort_keys=True, separators=(",", ":"))

    def _lock_for(self, event_id: str) -> asyncio.Lock:
        lock = self._event_locks.get(event_id)
        if lock is None:
            lock = asyncio.Lock()
            self._event_locks[event_id] = lock
        return lock

    async def handle_event(
        self,
        event_id: str,
        payload: dict,
        dispatch_fn: Callable[[dict], Awaitable[str]],
    ) -> dict:
        fp = self._fingerprint(payload)

        async with self._lock_for(event_id):
            existing_fp = self._payload_fingerprints.get(event_id)
            if existing_fp is not None and existing_fp != fp:
                raise ValueError(
                    f"Idempotency conflict: event_id {event_id!r} reused with different payload"
                )
            self._payload_fingerprints[event_id] = fp

            if event_id in self._results:
                return dict(self._results[event_id])

            try:
                job_id = await dispatch_fn(payload)
            except Exception:
                # Allow legitimate retries with the same payload when dispatch_fn fails
                if event_id not in self._results:
                    self._payload_fingerprints.pop(event_id, None)
                raise

            result = {
                "status": "dispatched",
                "event_id": event_id,
                "job_id": job_id,
            }
            self._results[event_id] = result
            return dict(result)

"""Reference solution for Drill 4: Single-LLM Action-Gating Execution Harness."""

from __future__ import annotations

import json
import re
from typing import Any, Awaitable, Callable


FALLBACK_REPLY = "I want to make sure I get this right — could you repeat what time works best for you?"
SLOT_CONFLICT_REPLY = "That time slot was just taken — let me check the next available time for you."

_FENCE_RE = re.compile(r"^\s*```(?:json)?\s*(.*?)\s*```\s*$", re.DOTALL | re.IGNORECASE)
_VALID_ACTIONS = {"BOOK", "ASK_CLARIFICATION", "NO_AVAILABILITY"}


def _parse_llm_json(raw: str) -> dict[str, Any] | None:
    if not isinstance(raw, str) or not raw.strip():
        return None
    cleaned = raw.strip()
    match = _FENCE_RE.match(cleaned)
    if match:
        cleaned = match.group(1).strip()
    try:
        parsed = json.loads(cleaned)
    except json.JSONDecodeError:
        return None
    return parsed if isinstance(parsed, dict) else None


async def execute_agent_turn(
    raw_llm_output: str,
    customer_id: str,
    open_slots: list[str],
    book_slot_fn: Callable[[str, str], Awaitable[bool]],
) -> dict:
    decision = _parse_llm_json(raw_llm_output)
    if decision is None:
        return {
            "action": "ASK_CLARIFICATION",
            "booked": False,
            "slot_id": None,
            "spoken_reply": FALLBACK_REPLY,
        }

    action = decision.get("action")
    spoken_reply = decision.get("spoken_reply")
    if action not in _VALID_ACTIONS or not isinstance(spoken_reply, str) or not spoken_reply.strip():
        return {
            "action": "ASK_CLARIFICATION",
            "booked": False,
            "slot_id": None,
            "spoken_reply": FALLBACK_REPLY,
        }

    if action == "BOOK":
        slot_id = decision.get("slot_id")
        allowed_slots = set(open_slots)
        if not isinstance(slot_id, str) or slot_id not in allowed_slots:
            return {
                "action": "ASK_CLARIFICATION",
                "booked": False,
                "slot_id": None,
                "spoken_reply": FALLBACK_REPLY,
            }

        was_booked = await book_slot_fn(customer_id, slot_id)
        if not was_booked:
            return {
                "action": "ASK_CLARIFICATION",
                "booked": False,
                "slot_id": None,
                "spoken_reply": SLOT_CONFLICT_REPLY,
            }

        return {
            "action": "BOOK",
            "booked": True,
            "slot_id": slot_id,
            "spoken_reply": spoken_reply,
        }

    return {
        "action": action,
        "booked": False,
        "slot_id": None,
        "spoken_reply": spoken_reply,
    }
